102. /** Messages the distiller ultimately reads (the selection budget). */
103. const ARCHIVE_EVENT_LIMIT = 1_000;
104. /** How far back selection looks. Wider than the budget so it can choose. */
105. const ARCHIVE_SCAN_LIMIT = 10_000;
