1802.     private _resolveProviderConfig(model?: string): Record<string, any> {
1803.         // 1. Try the multi-provider registry
1804.         const registry = this.workerDefaults.modelProviders;
1805.         if (registry) {
1806.             const resolved = registry.resolve(model);
1807.             if (resolved) {
1808.                 if (resolved.type === "github") {
1809.                     // GitHub provider — no SDK provider needed, uses gitHubToken on the client
1810.                     return {};
1811.                 }
1812.                 if (resolved.sdkProvider) {
1813.                     return { provider: resolved.sdkProvider };
1814.                 }
1815.             }
1816.         }
1817. 
1818.         // 2. Fall back to legacy single provider
1819.         const p = this.workerDefaults.provider;
1820.         if (!p) return {};
1821. 
1822.         // For Azure, dynamically construct deployment URL
1823.         if (p.type === "azure" && model && !p.baseUrl.includes("/deployments/")) {
1824.             return {
1825.                 provider: {
1826.                     ...p,
1827.                     baseUrl: `${p.baseUrl.replace(/\/+$/, "")}/deployments/${model}`,
1828.                 },
